<?php
declare(strict_types=1);
$root=dirname(__DIR__,2);require $root.'/espocrm/bootstrap.php';
use Espo\Core\Application;use Espo\Core\InjectableFactory;use Espo\Core\ORM\EntityManager;use Espo\Core\Tenant\TenantContext;use Espo\Core\Tenant\TenantContextStore;use Espo\Core\Tenant\TenantResolver;use Espo\Custom\Tools\LandingPage\LandingPageRenderer;use Espo\Custom\Tools\LandingPage\LandingPageService;
$assert=static function(bool $condition,string $message):void{if(!$condition)throw new RuntimeException($message);};$a=new TenantContext('30000000-0000-4000-8000-000000000001','isolation-alpha','landing-test');$b=new TenantContext('30000000-0000-4000-8000-000000000002','isolation-beta','landing-test');$app=new Application();$app->setupSystemUser();$container=$app->getContainer();$em=$container->getByClass(EntityManager::class);$store=$container->getByClass(TenantContextStore::class);$factory=$container->getByClass(InjectableFactory::class);$tx=$em->getTransactionManager();$tx->start();
try{$input=(object)['name'=>'Isolation landing test','slug'=>'isolation-landing-test','locale'=>'en','seoTitle'=>'Isolation landing test','seoDescription'=>'Tenant landing page isolation test.','primaryColor'=>'#087d71','backgroundColor'=>'#ffffff','textColor'=>'#172f35','blocks'=>[(object)['id'=>'hero-test','type'=>'hero','heading'=>'Tenant A','text'=>'Private draft and public snapshot.','buttonLabel'=>'Continue','buttonUrl'=>'/contact']]];$created=$store->runWith($a,fn():array=>$factory->create(LandingPageService::class)->save($input));$id=(string)$created['id'];$published=$store->runWith($a,fn():array=>$factory->create(LandingPageService::class)->publish($id));$assert(($published['version']??0)===1,'Landing page version was not published.');$alpha=$store->runWith($a,fn():array=>$factory->create(LandingPageService::class)->getWorkspace());$beta=$store->runWith($b,fn():array=>$factory->create(LandingPageService::class)->getWorkspace());$assert(count(array_filter($alpha['pages'],fn(array $page):bool=>$page['id']===$id))===1,'Tenant A cannot see its landing page.');$assert(count(array_filter($beta['pages'],fn(array $page):bool=>$page['id']===$id))===0,'Tenant B can see Tenant A landing page.');preg_match('#/p/([a-f0-9]{48})/([^/]+)$#',(string)$published['url'],$matches);$public=$store->runWith($a,fn():array=>$factory->create(LandingPageService::class)->published($matches[1],$matches[2]));$assert(($public['configuration']['blocks'][0]['heading']??null)==='Tenant A','Published snapshot is unavailable.');$resolved=$factory->create(TenantResolver::class)->resolveLandingPageKey($matches[1]);$assert($resolved?->tenantId===$a->tenantId,'Public landing-page key did not resolve to its tenant.');$html=$store->runWith($a,fn():string=>$factory->create(LandingPageRenderer::class)->render($matches[1],$matches[2]));$assert(str_contains($html,'Tenant A')&&str_contains($html,'<meta name="description"'),'Published landing page did not render.');$store->runWith($a,fn():array=>$factory->create(LandingPageService::class)->archive($id));$tx->rollback();}catch(Throwable $e){if($tx->isStarted())$tx->rollback();fwrite(STDERR,get_class($e).': '.$e->getMessage()."\n".$e->getTraceAsString()."\n");throw $e;}echo "Tenant landing page workspace tests passed.\n";
